class MerchandisingCommercialSeeder extends Seeder {
 public function run(): void {DB::transaction(function(){
  $p=EventProject::where('slug','os-jogos-do-agricultor')->first();$s=$p?->launchScenario();$pack=$p?WelcomePackPlan::where('event_project_id',$p->id)->first():null;if(!$s||!$pack||$p->commercial_policy_version)return;
  $p->update(['commercial_policy_version'=>'merch-break-even-v1']);
