   ['atelier-tina-textile','Atelier de Costura Tina · couture et applications','Duarte Simões, Centro Comercial da Estação, Loja 22, 6200-481 Covilhã',null,'https://atelierdatina.com/','Demander devis pour coudre des écussons sur 132 pièces, temps de préparation, disponibilité et essai sur la maille retenue. Vérifier adresse complète et horaires avant visite.'],
  ] as [$key,$name,$address,$phone,$source,$pitch])Prospect::firstOrCreate(['event_project_id'=>$p->id,'source_key'=>$key],['entity_key'=>$key,'name'=>$name,'category'=>'Textile / merchandising','municipality'=>'Covilhã','sector'=>'Covilhã','tour'=>'Covilhã · textile, appeler avant visite','address'=>$address,'phone'=>$phone,'source'=>$source,'checked_at'=>'2026-09-30','priority'=>2,'visit_order'=>90,'opportunity'=>$pitch,'next_action'=>'Qualifier atelier, motif, tailles et calendrier ; demander deux prototypes et devis, sans commande.']);
