   $line=$sp->budgetLine;if(!$line){$line=$s->budgetLines()->firstOrCreate(['costing_key'=>'commercial-'.$sp->template_key],['name'=>'Parrainage proposé · '.$sp->name,'kind'=>'revenue','scope'=>'structural','forecast_quantity'=>1,'unit'=>'contrat','pricing_status'=>'estimate']);$sp->update(['budget_line_id'=>$line->id]);}
   if($line->scenario_id===$s->id&&!$line->committed_quantity&&!$line->paid_quantity&&$line->unit_gross_cents===null)$line->update(['unit_gross_cents'=>$gross,'vat_basis_points'=>2300,'pricing_status'=>'estimate','price_source'=>'TARIF DE PROSPECTION, aucun accord. IVA simulée 23 % à qualifier. Principal 2 500 € TTC ; deux secondaires généraux 1 250 € TTC chacun. Parrains affectés : financement du coût connu, arrondi, périmètre à confirmer. Ne pas additionner une ligne structurelle globale active.','price_checked_at'=>'2026-09-30']);
  }
  $plan=CommercialPlan::firstOrCreate(['scenario_id'=>$s->id],['name'=>'6 + 6 · couvrir les frais et préparer la suite','assumptions'=>'Hypothèse de prospection : six indépendants à 650 € TTC ; six parrains de village portent le solde calculé après les autres partenariats proposés. Réserve de simulation pour inconnus 2 000 €, à ventiler par devis, en plus des imprévus existants. Objectif QAPAS existant conservé (4 000 € par mois au seed), pas de réduction tacite. 800 € de charges par édition au minimum, montant réel à qualifier. Hors profits espérés du bar, soupe, préventes, revente des gobelets et crédit bancaire. Aucun sponsor acquis. Aucun revenu de machine ou commande future supposé.']);
  $standLines=app(CommercialPricing::class)->lines($plan);if($standLines->count()===12&&$standLines->every(fn($l)=>$l->unit_gross_cents===50000&&!$l->committed_quantity&&!$l->paid_quantity&&$l->pricing_status==='estimate'))app(CommercialPricing::class)->apply($plan,true);
  foreach(['sponsor-main'=>250000,'sponsor-secondary'=>125000] as $key=>$amount){$offer=$p->offers()->where('template_key',$key)->first();if($offer&&$offer->price_gross_cents===null&&!$offer->is_public)$offer->update(['price_gross_cents'=>$amount,'delivery'=>'Proposition à négocier, IVA et prestations à confirmer. Aucun accord ni encaissement. Visibilité web contractuelle ; autres supports selon BAT, calendrier et périmètre.']);}
  foreach([['merch-prototypes','Confectionner deux prototypes pour la prospection','promotion','Deux tailles représentatives à essayer sur vêtement chaud. Photographier devant/dos à distance, tester lavage et confort ; pas de logo sponsor utilisé sans accord. Comparer variantes dans Merchandising.'],['commercial-prices','Valider les prix du socle 6 + 6','price','Devis complets, charges réelles, IA et frais personnels, affectations de sponsors, éventuel emprunt et réserve pour la suite. Vendre seulement des prestations chiffrées. Prix calculés ne prouvent pas une demande solvable.'],['actor-badges','Délivrer et tester les badges QR des acteurs','place','Personnes élues / QAPAS / service inscrites au relevé privé. Code officiel sans nom public, période, révocation et contrôle humain des accès sensibles. Un QR copié ne prouve pas l’identité.']] as [$key,$name,$pillar,$experiment])$p->ideas()->firstOrCreate(['template_key'=>$key],['name'=>$name,'pillar'=>$pillar,'hypothesis'=>$name,'experiment'=>$experiment,'depends_on'=>[],'is_public'=>false]);
  app(\App\Domain\Procurement\Consultations::class)->synchronize();
 });}
